function openModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
$('#modal-close').onclick=()=>$('#modal').close();
function readStore(key){if(db)return new Promise((resolve,reject)=>{const r=db.transaction('workspaces').objectStore('workspaces').get(key);r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});return Promise.resolve(JSON.parse(localStorage.getItem('docbench:'+key)||'null'));}
function writeStore(key,value){if(db)return new Promise((resolve,reject)=>{const t=db.transaction('workspaces','readwrite');t.objectStore('workspaces').put(value,key);t.oncomplete=resolve;t.onerror=()=>reject(t.error);});localStorage.setItem('docbench:'+key,JSON.stringify(value));return Promise.resolve();}
async function autoSave(){try{await writeStore('current',D.clone(ws));$('#save-status').textContent='このブラウザに保存済み';}catch(err){$('#save-status').textContent='自動保存できません';notify('自動保存できません。保存・読込からJSONを保存してください。');}}
