document.addEventListener('keydown',ev=>{if(!ev.defaultPrevented&&!ev.composedPath()[0]?.isContentEditable&&(ev.ctrlKey||ev.metaKey)&&ev.key.toLowerCase()==='z'&&!['INPUT','TEXTAREA'].includes(ev.target.tagName)&&!ev.target.isContentEditable){ev.preventDefault();$(ev.shiftKey?'#redo':'#undo').click();}});
