function styleForSelection(){const b=selectedDesignBlock(),s=D.settings({...activeDesign(),outputFormat:activeDocument().outputFormat||'html'});const editor=canvasController?.activeEditor?.();if(editor){const attrs=editor.getAttributes('textStyle'),st=D.blockStyle(b||{},s);return {...st,...Object.fromEntries(['bold','italic','underline','strike'].map(k=>[k,editor.isActive(k)])),font:attrs.fontFamily||st.font,align:editor.getAttributes(editor.isActive('heading')?'heading':'paragraph').textAlign||st.align,fontSize:attrs.fontSize?parseFloat(attrs.fontSize)*(attrs.fontSize.endsWith('px')?.75:1):editor.isActive('heading')?[22,18,16,14,12,11][Math.max(0,Math.min(5,(editor.getAttributes('heading').level||1)-1))]:st.fontSize,color:attrs.color||st.color,fill:attrs.backgroundColor||null};}if((activeDocument().outputFormat||'html')==='xlsx'&&canvasRange){const cell=D.colName(canvasRange.col)+canvasRange.row;return D.excelModel(ws.definition,{...activeDesign(),outputFormat:'xlsx'},ws.data.values).cells.find(c=>D.colName(c.col)+c.row===cell)?.style||D.blockStyle({},s);}return b?D.blockStyle(b,s,canvasPart):null;}
