 const selectedStyle=styleForSelection();if(selectedStyle){if(document.activeElement!==$('#canvas-font'))$('#canvas-font').value=selectedStyle.font;if(document.activeElement!==$('#canvas-font-size'))$('#canvas-font-size').value=selectedStyle.fontSize;$('#canvas-color').value=selectedStyle.color||s.color;$('#canvas-fill').value=selectedStyle.fill||'#ffffff';for(const key of ['bold','italic','underline','strike'])$('#canvas-'+key)?.setAttribute('aria-pressed',String(!!selectedStyle[key]));$$('[data-canvas-align]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.canvasAlign===selectedStyle.align)));if($('#canvas-slide'))$('#canvas-slide').value=b?.layout?.slide||1;if($('#canvas-rotation')){$('#canvas-rotation').value=b?.layout?.rotation||0;$('#canvas-rotation').disabled=!b||b.type==='table';}}
