 if($('#canvas-place'))$('#canvas-place').disabled=!b||!canvasRange;
 if(f==='xlsx'){for(const button of $$('[data-canvas-command]'))button.disabled=!b;if($('#sheet-merge'))$('#sheet-merge').disabled=!canvasRange;if($('#sheet-unmerge'))$('#sheet-unmerge').disabled=!canvasRange;}
 if(f==='docx'){const editor=canvasController?.activeEditor?.(),inTable=!!editor?.isActive('table');$('#word-table-tools').hidden=!inTable;$('#word-block-tools').hidden=!!editor||!b;$('#word-heading').disabled=!editor;if(editor&&document.activeElement!==$('#word-heading'))$('#word-heading').value=editor.isActive('heading')?String(editor.getAttributes('heading').level):'paragraph';for(const el of $$('[data-word-command]')){const op=el.dataset.wordCommand;el.disabled=op==='table'?false:!canvasController?.canCommand?.(op);if(['bulletList','orderedList','subscript','superscript'].includes(op))el.setAttribute('aria-pressed',String(!!editor?.isActive(op)));}for(const el of $$('[data-word-border]'))el.disabled=!inTable;const a=editor?.getAttributes(editor.isActive('tableHeader')?'tableHeader':'tableCell')||{};const cellKey=inTable?b?.id+':'+a.id:null;if(inTable&&cellKey!==wordCellSelectionKey){for(const [id,value] of [['word-cell-padding',a.padding??6],['word-cell-valign',a.valign||'top'],['word-cell-fill',a.fill||'#ffffff'],['word-cell-transparent',!a.fill]]){const el=$('#'+id);if(document.activeElement!==el){if(el.type==='checkbox')el.checked=value;else el.value=value;}}}wordCellSelectionKey=cellKey;}
 if(f==='xlsx'&&canvasRange){const key=D.colName(canvasRange.col)+canvasRange.row,model=D.excelModel(ws.definition,{...activeDesign(),outputFormat:'xlsx'},ws.data.values),cell=model.cells.find(c=>c.row===canvasRange.row&&c.col===canvasRange.col),block=activeDesign().blocks.find(b=>b.id===cell?.blockId),bound=!!block&&!['text','heading','rich'].includes(block.type);if(document.activeElement!==$('#sheet-address'))$('#sheet-address').value=key+(canvasRange.endRow!==canvasRange.row||canvasRange.endCol!==canvasRange.col?':'+D.colName(canvasRange.endCol)+canvasRange.endRow:'');if(document.activeElement!==$('#sheet-value'))$('#sheet-value').value=cell?.value??'';$('#sheet-value').readOnly=bound;$('#sheet-binding').textContent=bound?'入力フォームに連動':'';if(document.activeElement!==$('#sheet-number-format'))$('#sheet-number-format').value=cell?.style?.numberFormat||'General';}
