  if(type==='field'&&f==='docx'){b.type='rich';b.content=D.identifyRich({type:'doc',content:[{type:'paragraph',content:[{type:'fieldRef',attrs:{field:b.field,part:$('#word-field-part').value}}]}]});b.text=D.richSourceText(b.content);delete b.field;}
  else if(type==='shape'){b.shape='rect';b.style={border:'#172b39',fill:null};}else if(!['field','table'].includes(type))b.text=type==='heading'?'新しい見出し':'文章を入力';
  if(f==='pptx'){const page=D.settings({...d,outputFormat:f}),source=selectedDesignBlock()?.layout;b.layout={slide:source?.slide||1,x:1.6,y:3,w:Math.min(12,page.width-1.6),h:Math.min(type==='table'?5:2.5,page.height-3)};}
