 if($('#sheet-value')){$('#sheet-value').onchange=ev=>{if(!ev.target.readOnly&&canvasRange)canvasController?.value?.(D.colName(canvasRange.col)+canvasRange.row,ev.target.value);};$('#sheet-value').onkeydown=ev=>{if(ev.key==='Enter'){ev.preventDefault();$('#sheet-value').blur();canvasController?.sheet?.()?.updateSelectionFromCoords(canvasRange.col-1,canvasRange.row,canvasRange.col-1,canvasRange.row);}};$('#sheet-number-format').onchange=ev=>canvasStyle('numberFormat',ev.target.value);}
