  $$('.word-toolbar [role="toolbar"]').forEach(bar=>bar.addEventListener('keydown',ev=>{if(ev.target.tagName!=='BUTTON'||!['ArrowLeft','ArrowRight'].includes(ev.key))return;const controls=[...bar.querySelectorAll('button:not(:disabled),select:not(:disabled),input:not(:disabled),summary')].filter(el=>el.getClientRects().length),index=controls.indexOf(ev.target);if(index<0||!controls.length)return;ev.preventDefault();controls[(index+(ev.key==='ArrowRight'?1:-1)+controls.length)%controls.length].focus();}));
