  $$('[data-word-grid]').forEach(el=>{const size=el.dataset.wordGrid.split(',').map(Number);el.onmouseenter=()=>{$('#word-table-size').textContent=size[0]+'行 × '+size[1]+'列';$$('[data-word-grid]').forEach(b=>{const [r,c]=b.dataset.wordGrid.split(',').map(Number);b.classList.toggle('grid-active',r<=size[0]&&c<=size[1]);});};el.onfocus=el.onmouseenter;el.onclick=()=>{$('#word-table-rows').value=size[0];$('#word-table-cols').value=size[1];$('[data-word-command="table"]').click();};});
  $$('[data-word-border]').forEach(el=>el.onclick=()=>{canvasController?.command('borders',{preset:el.dataset.wordBorder,scope:$('#word-border-scope').value,color:$('#word-border-color').value,width:Number($('#word-border-width').value),style:$('#word-border-style').value});el.closest('.ribbon-details')?.removeAttribute('open');});
  $('#canvas-insert-type').onchange();
