function renderForm(){const total=ws.definition.fields.filter(f=>f.required).length,filled=ws.definition.fields.filter(f=>f.required&&ws.data.values[f.key]!==''&&ws.data.values[f.key]!==null&&ws.data.values[f.key]!==undefined).length;$('#app').innerHTML='<div class="intro"><div><h2>書類入力・出力</h2><p>'+e(ws.definition.description)+'</p></div><button id="validate" class="primary">入力を検証</button></div><div class="form-grid"><section class="panel"><div class="panel-head"><h3>書類への入力</h3><span class="badge">'+filled+' / '+total+' 必須項目</span></div><div class="panel-body"><div class="progress-track"><span style="width:'+(total?filled/total*100:100)+'%"></span></div><p class="muted">入力値は自動保存されます。共有するときは「保存・読込」から入力データを保存します。</p>'+issueList(errors)+formHTML()+'</div></section><section class="panel sticky"><div class="panel-head"><h3>書類プレビュー</h3><div class="export-bar"><label class="output-document-label">出力する書類<select id="output-document">'+documentOptions(activeDocument().id)+'</select></label><span class="badge">'+D.formatNames[activeDocument().outputFormat||'html']+'</span><button id="export-document" class="primary">出力</button></div></div><div class="paper-frame"><iframe id="document-preview" class="paper" title="書類プレビュー" sandbox=""></iframe></div><div class="panel-note">出力形式は書類出力定義で設定します。PDFはブラウザの印刷画面で保存します。</div></section></div>';$('#validate').onclick=()=>{errors=[...D.validateDefinition(ws.definition,ws.render).errors,...D.validateData(ws.definition,ws.data.values)];render();notify(errors.length?errors.length+'件の確認項目があります':'入力内容に問題はありません');};$('#export-document').onclick=exportDocument;$('#output-document').onchange=ev=>selectDocument(ev.target.value);bindForm();updatePreview();}
